reference_css:
* { box-sizing: border-box; }
:root { --ink: #172554; --muted: #475569; --line: #cbd5e1; --surface: #fff; --accent: #1d4ed8; --danger: #b91c1c; }
body { margin: 0; font: 1rem/1.6 system-ui, sans-serif; color: var(--ink); background: #eff6ff; }
.site-header { display: flex; justify-content: space-between; align-items: center; padding: 1rem max(1rem, calc((100vw - 72rem) / 2)); background: white; }
.brand { font-weight: 800; text-decoration: none; }
.page-shell { width: min(calc(100% - 2rem), 72rem); margin-inline: auto; }
.auth-layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(18rem, 1fr); align-items: start; gap: clamp(1.5rem, 4vw, 4rem); padding-block: 3rem; }
.auth-intro { padding-block: 2rem; }
h1 { font-size: clamp(2.25rem, 5vw, 4rem); line-height: 1.05; max-width: 12ch; }
.form-card { padding: clamp(1rem, 3vw, 2rem); border: 1px solid var(--line); border-radius: 1rem; background: var(--surface); box-shadow: 0 1rem 3rem rgb(23 37 84 / .08); }
.form-card h2 { margin-block-start: 0; }
.form-field { display: grid; gap: .4rem; margin-block: 1rem; }
label { font-weight: 700; }
input { width: 100%; min-width: 0; border: 1px solid #64748b; border-radius: .5rem; padding: .75rem; color: var(--ink); background: white; font: inherit; }
input:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
small, .fine-print, .site-note { color: var(--muted); }
.form-row { display: flex; flex-wrap: wrap; justify-content: space-between; gap: .75rem; margin-block: 1rem; }
.checkbox-label { display: flex; align-items: center; gap: .5rem; font-weight: 500; }
.checkbox-label input { width: auto; }
.button { width: 100%; border: 2px solid var(--accent); border-radius: .5rem; padding: .75rem 1rem; background: var(--accent); color: white; font: inherit; font-weight: 700; }
.button-secondary { color: var(--accent); background: white; }
.form-feedback { padding: .75rem; border-inline-start: 4px solid #1d4ed8; background: #eff6ff; }
hr { border: 0; border-top: 1px solid var(--line); margin-block: 2rem; }
@media (max-width: 48rem) { .auth-layout { grid-template-columns: 1fr; } .auth-intro { padding-block: 0; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; } }
